-- | ACVP test vectors for ML-KEM, from NIST's ACVP-Server.
--
-- Generated from gen-val/json-files/ML-KEM-{keyGen,encapDecap}-FIPS203, one
-- vector per parameter set per operation, and for the key checks one that
-- must be accepted and one that must be refused.  They are here rather than
-- downloaded when the suite runs, so that it needs no network and a release
-- tarball carries what it was tested against.
module PubKey.MLKEMVectors (
    KeyGenVector (..),
    EncapVector (..),
    DecapVector (..),
    KeyCheckVector (..),
    keyGenVectors,
    encapVectors,
    decapVectors,
    ekCheckVectors,
    dkCheckVectors,
) where

-- | The two seed halves in, the key pair out.
data KeyGenVector = KeyGenVector
    { kgSet :: String
    , kgId :: Int
    , kgD :: String
    , kgZ :: String
    , kgEk :: String
    , kgDk :: String
    }

-- | An encapsulation key and the message in, ciphertext and secret out.
data EncapVector = EncapVector
    { enSet :: String
    , enId :: Int
    , enEk :: String
    , enM :: String
    , enC :: String
    , enK :: String
    }

-- | A decapsulation key and a ciphertext in, the secret out.
data DecapVector = DecapVector
    { deSet :: String
    , deId :: Int
    , deDk :: String
    , deC :: String
    , deK :: String
    }

-- | A key that the checks of FIPS 203 7.2 and 7.3 must accept or refuse.
data KeyCheckVector = KeyCheckVector
    { ckSet :: String
    , ckId :: Int
    , ckKey :: String
    , ckPasses :: Bool
    }

